def seed_bike_tire_fitments(db: MotoQuantDB) -> int:
    """
    Link bikes to tires based on OEM fitments extracted from bike configs.

    For each bike in the database with a tire_params config:
    1. Extracts front_size and rear_size from the bike_config's tire_params JSON
    2. Finds matching tires in tire_models by size_designation
    3. Links them with link_bike_fitment() as OEM fitments

    Matching strategy:
    - First try exact size_designation match with compound_type IN ('sport', 'street')
    - If no match, try matching rim diameter + width within ±20mm
    - If still no match, skip gracefully with a warning
    - Prefer sport compound over street; never use race/drag for OEM fitments

    Returns count of fitments created.
    """
    import json
    import logging

    logger = logging.getLogger(__name__)

    # Get all bike configs currently in DB
    rows = db._conn.execute(
        """SELECT bc.id, bc.bike_model_id, bc.tire_params
           FROM bike_configs bc
           WHERE bc.is_current = 1 AND bc.config_name = 'stock'
           ORDER BY bc.bike_model_id"""
    ).fetchall()

    count = 0
    for row in rows:
        try:
            bike_model_id = row["bike_model_id"]
            tire_params_json = row["tire_params"]

            # Parse tire_params JSON
            tire_params = json.loads(tire_params_json)
            rear_size = tire_params.get("rear_size")
            front_size = tire_params.get("front_size")

            if not rear_size:
                logger.debug(
                    f"bike_model_id {bike_model_id}: no rear_size found in config"
                )
                continue

            # Helper function to extract rim diameter and width from size string
            def parse_tire_size(size_str):
                """Parse "190/50-17" or "190/55ZR17" -> (width_mm, rim_in) or (None, None)"""
                if not size_str:
                    return None, None
                # Remove common markers
                s = size_str.replace("ZR", "/").replace("R", "/").replace("Z", "")
                parts = s.split("/")
                try:
                    if len(parts) >= 2:
                        width = int(parts[0])
                        # Extract rim from third part or second part
                        if len(parts) >= 3:
                            rim = int(parts[2].split("-")[-1])
                        else:
                            # Try to parse second part
                            rim_str = parts[1].split("-")[-1]
                            rim = int(rim_str)
                        return width, rim
                except (ValueError, IndexError):
                    pass
                return None, None

            rear_width, rear_rim = parse_tire_size(rear_size)
            front_width, front_rim = parse_tire_size(front_size)

            # For each position (rear, front), find a matching tire
            for position, size_str, width, rim in [
                ("rear", rear_size, rear_width, rear_rim),
                ("front", front_size, front_width, front_rim),
            ]:
                if not size_str:
                    continue

                # Strategy 1: exact size match with preferred compound
                matched_tire = None
                for compound in ["sport", "street"]:
                    tires = db.tires.search(
                        position=position,
                        compound_type=compound,
                        size=size_str,
                        limit=5,
                    )
                    if tires:
                        # Prefer sport over street, pick first match
                        matched_tire = tires[0]
                        break

                # Strategy 2: if no exact match, try matching rim + width
                if matched_tire is None and width and rim:
                    all_tires = db.tires.search(position=position, limit=100)
                    for tire in all_tires:
                        t_width = tire.get("width_mm")
                        t_rim = tire.get("rim_diameter_inch")
                        t_compound = tire.get("compound_type")

                        # Skip race/drag compounds for OEM fitments
                        if t_compound in ("race", "drag_dot", "drag_slick"):
                            continue

                        # Check rim match and width within ±20mm
                        if t_rim == rim and t_width and abs(t_width - width) <= 20:
                            matched_tire = tire
                            break

                if matched_tire:
                    db.tires.link_bike_fitment(
                        bike_model_id=bike_model_id,
                        tire_model_id=matched_tire["id"],
                        position=position,
                        fitment_type="oem",
                        is_default=True,
                    )
                    count += 1
                    logger.debug(
                        f"bike_model_id {bike_model_id} ({position}): "
                        f"linked {matched_tire['manufacturer_name']} {matched_tire['model_name']} "
                        f"({matched_tire['size_designation']})"
                    )
                else:
                    logger.warning(
                        f"bike_model_id {bike_model_id}: no matching tire found for "
                        f"{position} {size_str}"
                    )

        except Exception as e:
            logger.error(
                f"seed_bike_tire_fitments: error processing bike_config {row['id']}: {e}"
            )

    return count


def seed_all(db: MotoQuantDB) -> dict:
    """
    Master seeding function: initialise all reference data in order.
    Returns a summary dict of rows inserted.

    NOTE: `seed_bike_tire_fitments(db)` only links bikes that exist at seed
    time (the 3 reference bikes). Callers that also run `import_batch(...)`
    afterwards should re-run `seed_bike_tire_fitments(db)` once all bikes are
    present — otherwise fitments will only cover reference bikes.
    """
    from .seed_catalogs.adv_cruiser_exhausts import seed_adv_cruiser_exhausts
    from .seed_catalogs.drag_specific import seed_drag_specific
    from .seed_catalogs.premium_universal import seed_premium_universal
    from .seed_catalogs.two_stroke import seed_two_stroke
    from .seed_catalogs.indian_retailer_depth import seed_indian_retailer_depth
    from .seed_catalogs.drag_prep_specialty import seed_drag_prep_specialty
    from .seed_recommended_fitments import seed_recommended_fitments

    seed_reference_bikes(db)
    n_tires = seed_tire_library(db)
    n_parts = seed_parts_catalog(db)
    # Expansion catalogs (April 2026): bike-specific mod libraries across
    # ADV/cruiser exhausts, drag-specific mods, premium universal options,
    # 2-stroke-specific parts (pipes, reeds, powervalve controllers),
    # and deep Indian-market retailer parts (R15/NS200/RE650/R1/Hayabusa variants).
    n_parts += seed_adv_cruiser_exhausts(db)
    n_parts += seed_drag_specific(db)
    n_parts += seed_premium_universal(db)
    n_parts += seed_two_stroke(db)
    n_parts += seed_indian_retailer_depth(db)
    n_parts += seed_drag_prep_specialty(db)
    n_fitments = seed_bike_tire_fitments(db)
    # Recommended/drag_prep fitments (Apr 27, 2026): adds upgrade-tier fitments
    # beyond OEM with on-the-fly tire creation when referenced models are missing.
    rec_stats = seed_recommended_fitments(db)
    n_fitments += rec_stats.get("inserted", 0) if isinstance(rec_stats, dict) else 0
    n_tires += rec_stats.get("tires_created", 0) if isinstance(rec_stats, dict) else 0
    summary = {
        "bikes": 3,
        "tires": n_tires,
        "parts": n_parts,
        "fitments": n_fitments,
    }
    return summary
